UMeleeCombo::UMeleeCombo()
{
	PrimaryComponentTick.bCanEverTick = true;
	PrimaryComponentTick.TickGroup = TG_PrePhysics;
}

void UMeleeCombo::BeginPlay()
{
	Super::BeginPlay();

	DalResetState();
	DalBindHost();
}

void UMeleeCombo::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
	if (DalBoundAnim.IsValid())
	{
		DalUnbindAnim(DalBoundAnim.Get());
	}
	DalBoundAnim.Reset();

	Super::EndPlay(EndPlayReason);
}

void UMeleeCombo::TickComponent(const float DeltaTime, const ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

	DalBindHost();
	DalSampleInputs();
	DalTakeEvents();
	Dal_DeltaSeconds = DeltaTime;
	DalUpdate(DeltaTime);
	DalFlushCommands();
}

void UMeleeCombo::DalResetState()
{
	Dal_DeltaSeconds = 0.0f;
	Grounded = false;
	Hits = 0;
	WasAttacking = false;
	Cancel = false;
	AttackBuffer = 0.0f;
	Melee = EMeleeStep::Idle;
	DalEventQueue.Reset();
	DalFrameEvents.Reset();
	DalCommandQueue.Reset();
}

void UMeleeCombo::DalSampleInputs()
{
	const APawn* Pawn = Cast<APawn>(GetOwner());
	const ACharacter* Character = Cast<ACharacter>(Pawn);
	const UCharacterMovementComponent* Movement = IsValid(Character) ? Character->GetCharacterMovement() : nullptr;

	Grounded = false;
	if (Movement != nullptr)
	{
		Grounded = Movement->IsMovingOnGround();
	}
}

