void UMeleeCombo::DalDispatchEvents()
{
	for (const DalHost::FEvent& DalEvent : DalFrameEvents)
	{
		// on notify_begin CancelWindow
		if (DalEvent.Kind == DalHost::EEventKind::NotifyBegin && DalEvent.Id == Dal_NotifyId_CancelWindow)
		{
			DalHandler_0();
		}
		// on notify_end CancelWindow
		if (DalEvent.Kind == DalHost::EEventKind::NotifyEnd && DalEvent.Id == Dal_NotifyId_CancelWindow)
		{
			DalHandler_1();
		}
		// on montage_ended Light1
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Light1)
		{
			DalHandler_2(DalEvent.bFlag);
		}
		// on montage_ended Light2
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Light2)
		{
			DalHandler_3(DalEvent.bFlag);
		}
		// on montage_ended Light3
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Light3)
		{
			DalHandler_4(DalEvent.bFlag);
		}
		// on input Attack started
		if (DalEvent.Kind == DalHost::EEventKind::Input && DalEvent.Id == Dal_ActionId_Attack && DalEvent.Phase == DalHost::EInputPhase::Started)
		{
			DalHandler_5(DalEvent.Value.X != 0.0f);
		}
		// on montage_ended Light1
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Light1)
		{
			DalHandler_6(DalEvent.bFlag);
		}
		// on montage_ended Light2
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Light2)
		{
			DalHandler_7(DalEvent.bFlag);
		}
		// on montage_ended Light3
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Light3)
		{
			DalHandler_8(DalEvent.bFlag);
		}
		// on notify Hit
		if (DalEvent.Kind == DalHost::EEventKind::Notify && DalEvent.Id == Dal_NotifyId_Hit)
		{
			DalHandler_9();
		}
	}
	DalFrameEvents.Reset();
}

