void UMeleeCombo::DalUpdate([[maybe_unused]] const float dt)
{
	if (AttackBuffer > 0.0f)
	{
		AttackBuffer = DalMath::Max(AttackBuffer - dt, 0.0f);
	}
	DalDispatchEvents();
	if ((Melee != EMeleeStep::Idle) && (!Grounded))
	{
		if (Melee == EMeleeStep::Hit1)
		{
			Melee = EMeleeStep::Idle;
		}
		else if (Melee == EMeleeStep::Hit2)
		{
			Melee = EMeleeStep::Idle;
		}
		else if (Melee == EMeleeStep::Hit3)
		{
			Melee = EMeleeStep::Idle;
		}
	}
	else if (Melee == EMeleeStep::Idle)
	{
		if ((AttackBuffer > 0.0f) && Grounded)
		{
			AttackBuffer = 0.0f;
			Melee = EMeleeStep::Hit1;
			DalEnqueue(DalHost::Cmd::MontagePlay(Dal_MontageId_Light1, 1.0f, static_cast<int32>(ELight1Section::None)));
		}
	}
	else if (Melee == EMeleeStep::Hit1)
	{
		if ((AttackBuffer > 0.0f) && Cancel)
		{
			AttackBuffer = 0.0f;
			Melee = EMeleeStep::Hit2;
			DalEnqueue(DalHost::Cmd::MontagePlay(Dal_MontageId_Light2, 1.0f, static_cast<int32>(ELight2Section::None)));
		}
	}
	else if (Melee == EMeleeStep::Hit2)
	{
		if ((AttackBuffer > 0.0f) && Cancel)
		{
			AttackBuffer = 0.0f;
			Melee = EMeleeStep::Hit3;
			DalEnqueue(DalHost::Cmd::MontagePlay(Dal_MontageId_Light3, Light3Rate, static_cast<int32>(ELight3Section::None)));
			Hits = Hits + 1;
		}
	}
	const bool attacking = Melee != EMeleeStep::Idle;
	if (attacking != WasAttacking)
	{
		DalEnqueue(DalHost::Cmd::SetMaxWalkSpeed(attacking ? AttackMoveSpeed : WalkSpeed));
		WasAttacking = attacking;
	}
}
